sys_script_email.script:
(function runMailScript(current, template, email, email_action, event) {

    var offeringId = current.getValue('service_offering');

    if (!offeringId) {
        gs.warn('[Outage Shield] Notification has no Service Offering');
        return;
    }

    var subscriptions = new GlideRecord('service_subscribe_sys_user');
    subscriptions.addQuery('service_offering', offeringId);
    subscriptions.query();

    var seen = {};
    var count = 0;

    while (subscriptions.next()) {

        var user = new GlideRecord('sys_user');

        if (!user.get(subscriptions.getValue('sys_user')))
            continue;

        if (user.getValue('active') !== '1' &&
            user.getValue('active') !== 'true')
            continue;

        var address = String(user.getValue('email') || '').trim();

        if (!address || seen[address.toLowerCase()])
            continue;

        seen[address.toLowerCase()] = true;

        email.addAddress(
            'to',
            address,
            user.getDisplayValue()
        );

        count++;
    }

    gs.info('[Outage Shield] Notification subscribers added: ' + count);

})(current, template, email, email_action, event);
